import AppKit

extension VideoPane {
    // MARK: Obscure

    /// The obscured regions (§4.3's phase-3c list, schema version 4): boxes
    /// on the layer whose contents are blurred or pixelated so a face, a
    /// password field or a notification cannot be read.
    ///
    /// It is the spotlight's inverse and it is spelled in the spotlight's
    /// frame — `x`/`y` are the region's CENTRE and `width`/`height` its size,
    /// both in SOURCE pixels from the centre of the cropped rect — so a
    /// region rides with its layer through scale, move and rotation, and the
    /// same four numbers typed into Spotlight put a box in the same place.
    /// That is also why the numeric rows are plain px fields rather than
    /// percentages, and why a centre outside the layer is allowed.
    ///
    /// **It is a LIST, so it takes `filtersSection`'s shape and its warning
    /// with it.** Nothing here is a general-purpose list editor and it must
    /// not become one: the cap is four, so every region is on screen at
    /// once; the rows are built against a FIXED INDEX (the count is in
    /// `structureSignature`, so add and remove rebuild the pane while
    /// dialling a value merely refreshes it); an index the model no longer
    /// holds yields the list unchanged, which the core answers as the
    /// identity it is; and every write sends the WHOLE array through an
    /// ordinary `set_video` patch, which is what keeps add and remove out of
    /// the op table (`actions::merge` replaces arrays wholesale).
    ///
    /// **Adding and removing a region change the CLIP**, not the action under
    /// the playhead — including "Place on Canvas", which is an append like
    /// any other. A list of a different length in an action's end patch
    /// cannot interpolate, so an appended region would be invisible for the
    /// whole span and gone at the next write; dialling an existing region's
    /// amount or box still belongs to the action, which is what §3c's
    /// interpolation rule is for. `InspectorBinding.structural(video:for:)`
    /// decides it, for this list and the filter stack alike, and argues it in
    /// full.
    ///
    /// Order does NOT matter here, unlike the filter stack: where two
    /// regions overlap the shader takes the STRONGER of them per fragment,
    /// so there is no position popup to move a region up or down and the
    /// label column carries the region's number instead.
    ///
    /// **One "Place on Canvas", not one per row.** It appends, and it is
    /// disabled at the cap. `InspectorViewController.onCommand` is
    /// `(Selector) -> Void` and carries no index (`inspectorCommand` sends a
    /// nil sender), so a per-row button would need an index-carrying seam of
    /// its own — the first of its kind, added for one button, against the
    /// warning above. A region placed on the canvas is edited in its row like
    /// any other.
    func obscureSection() -> InspectorSection {
        let binding = self.binding
        let shapes = SpotShape.allCases
        let kinds = ObscureKind.allCases
        func list() -> [ObscureProps] { binding.videoProps.obscure }
        func at(_ index: Int) -> ObscureProps? {
            let regions = list()
            return regions.indices.contains(index) ? regions[index] : nil
        }
        func ops(_ next: [ObscureProps]) -> [ReelOp] {
            binding.ops(video: VideoPatch(obscure: next))
        }
        /// The read/write split the filter stack takes, for the same reason
        /// and out of the same reader: inside an action a write REPLACES the
        /// end patch's array whole, so building it from the interpolated
        /// regions would pin every one the user did not touch — and with
        /// eight fields a region, seven of them ride along on every edit.
        func writeList() -> [ObscureProps] {
            binding.editedList(action: { $0.obscure }, base: { $0.obscure })
        }
        func writeAt(_ index: Int) -> ObscureProps? {
            let regions = writeList()
            return regions.indices.contains(index) ? regions[index] : nil
        }
        func replacing(_ index: Int, _ next: ObscureProps) -> [ObscureProps] {
            var regions = writeList()
            guard regions.indices.contains(index) else { return regions }
            regions[index] = next
            return regions
        }
        /// One region with `change` applied, the other fields as they stand —
        /// `spotlightSection`'s `edited { … }` over a list. Eight fields is
        /// enough that spelling all of them out at every row would bury the
        /// one that changes. No change is the region rewritten as it is.
        func edited(
            _ index: Int, _ change: (inout ObscureProps) -> Void = { _ in }
        ) -> [ReelOp] {
            // `writeAt`, not `at`: the seven fields that ride along are the
            // ones the edit is replacing, never the ones the playhead shows.
            guard var o = writeAt(index) else { return [] }
            change(&o)
            return ops(replacing(index, o))
        }
        /// The mixed badge for one region's field: a selection where some
        /// clip has no region at that index disagrees, which the `nil` says.
        func mixedAt<T: Equatable>(_ index: Int, _ read: @escaping (ObscureProps) -> T) -> Bool {
            binding.mixedVideo { props in
                props.obscure.indices.contains(index) ? read(props.obscure[index]) : nil
            }
        }
        /// The paired numeric boxes. Centre and size get two fields on one
        /// row rather than the four separate value rows the spotlight gives
        /// them: four regions × eight rows would be a section nobody can see
        /// the end of, and neither pair wants a slider anyway (§4.3 gives
        /// the spotlight's own centre and size `slider: false`).
        func field(
            _ index: Int, name: String, min lower: Double, max upper: Double,
            quick: [Double] = [], read: @escaping (ObscureProps) -> Double,
            write: @escaping (Int, Double) -> [ReelOp]
        ) -> OptionFieldControl {
            OptionFieldControl(
                width: InspectorMetrics.fieldWidth, unit: " px", decimals: 0, min: lower,
                max: upper, quick: quick,
                read: { at(index).map(read) ?? 0 },
                write: { value in binding.apply(name, write(index, value)) },
                enabled: { true },
                onEdit: { binding.edited() })
        }

        let count = list().count
        var rows: [NSView] = []
        for index in 0..<count {
            let kind = OptionPopupControl(
                width: 96, items: kinds.map { $0.displayName },
                read: { kinds.firstIndex(of: at(index)?.kind ?? .pixelate) ?? 0 },
                write: { choice in
                    guard kinds.indices.contains(choice) else { return }
                    binding.apply("Obscure Kind", edited(index) { $0.kind = kinds[choice] })
                },
                enabled: { true },
                onEdit: { binding.edited() })
            kind.toolTip = "Pixelate hides; blur softens"
            let remove = OptionButtonControl(
                title: "Remove",
                action: {
                    var next = list()
                    guard next.indices.contains(index) else {
                        NSSound.beep()
                        return
                    }
                    next.remove(at: index)
                    binding.apply("Remove Region", ops(next))
                },
                enabled: { true }, onEdit: {})
            remove.toolTip =
                "Take this region off the clip — the clip itself, not the action "
                + "under the playhead"
            rows.append(
                inspectorRow(
                    "Region \(index + 1)", [kind, remove],
                    mixed: { mixedAt(index) { $0.kind } },
                    binding: binding, writes: edited(index)))
            rows.append(
                inspectorPopupRow(
                    "Shape", binding, name: "Obscure Shape",
                    items: shapes.map { $0.displayName },
                    read: { shapes.firstIndex(of: at(index)?.shape ?? .rect) ?? 0 },
                    ops: { choice in
                        guard shapes.indices.contains(choice) else { return [] }
                        return edited(index) { $0.shape = shapes[choice] }
                    },
                    mixed: { mixedAt(index) { $0.shape } }))
            rows.append(
                inspectorValueRow(
                    "Amount", binding, name: "Obscure Amount", unit: "%", decimals: 0, min: 0,
                    max: 100, quick: [0, 25, 50, 75, 100],
                    read: { (at(index)?.amount ?? 0) * 100 },
                    ops: { v in edited(index) { $0.amount = v / 100 } },
                    mixed: { mixedAt(index) { $0.amount } }))
            rows.append(
                inspectorValueRow(
                    "Feather", binding, name: "Obscure Feather", unit: " px", decimals: 0,
                    min: 0, max: 200, quick: [0, 10, 20, 40, 80],
                    read: { at(index)?.feather ?? 0 },
                    ops: { v in edited(index) { $0.feather = v } },
                    mixed: { mixedAt(index) { $0.feather } }))
            rows.append(
                inspectorRow(
                    "Center",
                    [
                        field(
                            index, name: "Obscure Center", min: -20000, max: 20000,
                            read: { $0.x }, write: { i, value in edited(i) { $0.x = value } }),
                        field(
                            index, name: "Obscure Center", min: -20000, max: 20000,
                            read: { $0.y }, write: { i, value in edited(i) { $0.y = value } }),
                    ],
                    mixed: { mixedAt(index) { $0.x } || mixedAt(index) { $0.y } },
                    binding: binding, writes: edited(index)))
            // The core takes width and height as strictly greater than zero
            // (`above`, not `at_least`), exactly as it does the spotlight's:
            // a region with no area hides nothing and cannot be grabbed back,
            // so the field's floor is one pixel rather than nought.
            rows.append(
                inspectorRow(
                    "Size",
                    [
                        field(
                            index, name: "Obscure Size", min: 1, max: 20000,
                            quick: [120, 240, 480, 960], read: { $0.width },
                            write: { i, value in edited(i) { $0.width = value } }),
                        field(
                            index, name: "Obscure Size", min: 1, max: 20000,
                            quick: [68, 135, 270, 540], read: { $0.height },
                            write: { i, value in edited(i) { $0.height = value } }),
                    ],
                    mixed: { mixedAt(index) { $0.width } || mixedAt(index) { $0.height } },
                    binding: binding, writes: edited(index)))
        }
        if count == 0 {
            rows.append(inspectorRow(nil, [InspectorRowLabel("No obscured regions.")]))
        }
        let add = OptionButtonControl(
            title: "Add Region",
            action: {
                var next = list()
                guard next.count < ObscureProps.max else {
                    NSSound.beep()
                    return
                }
                next.append(ObscureProps())
                binding.apply("Add Region", ops(next))
            },
            enabled: { list().count < ObscureProps.max }, onEdit: {})
        add.toolTip =
            "Add a 480 × 270 pixelated box at the centre of the layer — on the clip "
            + "itself, not on the action under the playhead"
        let place = commandButton(
            "Place on Canvas", #selector(EditorViewController.placeObscureRegion(_:)),
            toolTip:
                "Drag a rectangle on the canvas (Esc cancels) — it is appended to the clip "
                + "itself, not to the action under the playhead",
            enabled: { list().count < ObscureProps.max })
        rows.append(
            inspectorButtonRow([add, place, InspectorRowLabel("\(ObscureProps.max) at most")]))

        return InspectorSection(
            id: "video.obscure", title: "Obscure",
            summary: {
                let regions = list()
                guard !regions.isEmpty else { return "none" }
                return regions.count == 1
                    ? regions[0].kind.displayName.lowercased() : "\(regions.count) regions"
            },
            reset: { binding.apply("Obscure", video: VideoPatch(obscure: [])) },
            differs: { !list().isEmpty },
            defaultExpanded: false,
            rows: rows)
    }
}
import AppKit

/// The Picture sub-tab's Hide While Silent section (road map creator-jobs CO9,
/// spec §11 CO-94): the camera fades out in the pauses of a media's speech
/// and back in just before it (CO-90). After Layout, shut by default.
///
/// Every row is one undo step "Hide While Silent" and writes the WHOLE gate to
/// the base (`structural(video:for:)`: it is not an animation target), each
/// edit re-sending the other values as they stand (the Ducking section's
/// rule). A gate naming a media whose speech is not saved yet carries that
/// media's `set_media_speech` first, in the same step, as Duck by Speech does
/// (`DuckSpeech.ops(forMedia:)`); a refusal there sends nothing, and the
/// section's note says why.
extension VideoPane {

    /// Every selected clip draws pixels and none is a nest clip (a nest scope
    /// is allowed): a nest clip never draws itself (CO-92).
    var allHideable: Bool {
        let clips = binding.clips
        return !clips.isEmpty
            && clips.allSatisfy { clip in
                if case .nest = clip.source { return false }
                return InspectorTab.hasPixels(clip, in: binding.snapshot)
            }
    }

    func hideSilentSection() -> InspectorSection {
        let binding = self.binding
        let name = "Hide While Silent"
        /// The sentence of the last refused `ops(forMedia:)`, shown as the note.
        final class Problem { var text: String? }
        let problem = Problem()
        func candidates() -> [MediaSnapshot] {
            HideSilentSources.candidates(for: binding.clips, in: binding.snapshot)
        }
        func gated() -> [ClipSnapshot] { binding.videoClips.filter { $0.video?.hideSilent != nil } }
        func anyOn() -> Bool { !gated().isEmpty }
        func allOn() -> Bool {
            !binding.videoClips.isEmpty && gated().count == binding.videoClips.count
        }
        func current() -> HideSilentProps? { gated().first?.video?.hideSilent }
        /// The media's `set_media_speech` ops, or nil when `ops(forMedia:)`
        /// refused: then the row writes nothing and the note says why.
        func spans(_ media: UInt32) -> [ReelOp]? {
            do {
                let ops = try DuckSpeech.ops(
                    forMedia: media, in: binding.snapshot,
                    cacheDirectory: binding.document?.cacheDirectory)
                problem.text = nil
                return ops
            } catch {
                problem.text = error.localizedDescription
                return nil
            }
        }
        /// The whole gate `next` on every selected picture clip, the spans first.
        func write(_ next: HideSilentProps) -> [ReelOp] {
            guard let speech = spans(next.media) else { return [] }
            return speech + binding.ops(video: VideoPatch(hideSilent: .some(next)))
        }
        func onOps() -> [ReelOp] {
            guard let first = candidates().first else { return [] }
            let gate = HideSilentProps(media: first.id)
            let set = binding.videoClips.filter { $0.video?.hideSilent == nil }.flatMap {
                binding.ops(video: VideoPatch(hideSilent: .some(gate)), for: $0)
            }
            guard !set.isEmpty, let speech = spans(gate.media) else { return [] }
            return speech + set
        }
        func offOps() -> [ReelOp] { binding.ops(video: VideoPatch(hideSilent: .some(nil))) }
        func offerable() -> Bool {
            guard let first = candidates().first else { return false }
            return DuckSpeech.problem(
                forMedia: first.id, in: binding.snapshot,
                cacheDirectory: binding.document?.cacheDirectory) == nil
        }
        /// "Speech from"'s media: the candidates, then the set media when it
        /// is not among them.
        func sources() -> [MediaSnapshot] {
            var list = candidates()
            if let set = current()?.media, !list.contains(where: { $0.id == set }),
               let row = binding.snapshot.media(set)
            {
                list.append(row)
            }
            return list
        }
        let sourceList = sources()
        func seconds(_ ticks: Ticks) -> Double { ReelTime.seconds(ticks) }
        func ticks(_ seconds: Double) -> Ticks { ReelTime.ticks(seconds: max(seconds, 0)) }
        func edit(_ change: (inout HideSilentProps) -> Void) -> [ReelOp] {
            guard var next = current() else { return [] }
            change(&next)
            return write(next)
        }

        let check = OptionCheckboxControl(
            label: "Hide while silent", read: allOn,
            write: { value in binding.apply(name, value ? onOps() : offOps()) },
            enabled: { anyOn() || offerable() }, onEdit: { binding.edited() })
        if !anyOn(), let first = candidates().first {
            check.toolTip = DuckSpeech.problem(
                forMedia: first.id, in: binding.snapshot,
                cacheDirectory: binding.document?.cacheDirectory)
        } else if candidates().isEmpty, !anyOn() {
            check.toolTip = "No clip with sound plays under the selection."
        }
        return InspectorSection(
            id: "video.hide_silent", title: "Hide While Silent",
            summary: {
                guard anyOn() else { return "off" }
                let media = Set(gated().map { $0.video?.hideSilent?.media ?? 0 })
                guard allOn(), media.count == 1, let id = media.first,
                      let row = binding.snapshot.media(id)
                else { return "on" }
                return row.name
            },
            note: { problem.text },
            reset: { binding.apply(name, offOps()) },
            defaultExpanded: false,
            rows: [
                inspectorRow(
                    nil, [check], mixed: { anyOn() && !allOn() }, binding: binding,
                    writes: offOps(),
                    default: InspectorRowDefault(name: name, differs: anyOn, ops: offOps)),
                inspectorPopupRow(
                    "Speech from", binding, name: name, items: sourceList.map(\.name),
                    read: {
                        sourceList.firstIndex { $0.id == current()?.media } ?? 0
                    },
                    ops: { index in
                        guard sourceList.indices.contains(index) else { return [] }
                        return edit { $0.media = sourceList[index].id }
                    },
                    mixed: { binding.mixedVideo { $0.hideSilent?.media } },
                    enabled: anyOn, resets: false),
                inspectorValueRow(
                    "Pre-roll", binding, name: name, unit: " s", decimals: 2, min: 0, max: 5,
                    quick: [0, 0.1, 0.2, 0.5],
                    read: { seconds(current()?.preRoll ?? HideSilentProps.defaultPreRoll) },
                    ops: { value in edit { $0.preRoll = ticks(value) } },
                    mixed: { binding.mixedVideo { $0.hideSilent?.preRoll } },
                    enabled: anyOn),
                inspectorValueRow(
                    "Hold", binding, name: name, unit: " s", decimals: 2, min: 0, max: 5,
                    quick: [0.5, 1, 1.5, 3],
                    read: { seconds(current()?.hold ?? HideSilentProps.defaultHold) },
                    ops: { value in edit { $0.hold = ticks(value) } },
                    mixed: { binding.mixedVideo { $0.hideSilent?.hold } },
                    enabled: anyOn),
                inspectorValueRow(
                    "Fade", binding, name: name, unit: " s", decimals: 2, min: 0, max: 5,
                    quick: [0, 0.15, 0.3, 0.5],
                    read: { seconds(current()?.fade ?? HideSilentProps.defaultFade) },
                    ops: { value in edit { $0.fade = ticks(value) } },
                    mixed: { binding.mixedVideo { $0.hideSilent?.fade } },
                    enabled: anyOn),
            ])
    }
}
import Foundation

// MARK: - Hide while silent

// The Swift half of `video.hide_silent` (format 43, road map creator-jobs CO9,
// spec §11 CO-90…CO-94): the props the model stores, the media a person can
// pick the speech from, and the plan's `gates` read back for the timeline's
// line. **Rust decides the gate**: where a media's speech plays, which
// container it is read in and how the opacity ramps are
// `core/src/video_gate.rs`'s. Nothing here maps a span to the timeline or
// computes an opacity.

/// A clip's `video.hide_silent` (CO-90, CO-91): the media whose speech the
/// clip follows and the envelope around it, in ticks, stored as typed (off
/// the frame grid). Every write names all four keys (`dictionary`).
struct HideSilentProps: Codable, Equatable {
    var media: UInt32
    var preRoll: Ticks
    var hold: Ticks
    var fade: Ticks

    /// 0.2 s, 1.5 s and 0.3 s, and each one's top, 5 s (the core's
    /// `HIDE_SILENT_*`).
    static let defaultPreRoll: Ticks = 120_000
    static let defaultHold: Ticks = 900_000
    static let defaultFade: Ticks = 180_000
    static let maxTicks: Ticks = 3_000_000

    init(
        media: UInt32, preRoll: Ticks = defaultPreRoll, hold: Ticks = defaultHold,
        fade: Ticks = defaultFade
    ) {
        self.media = media
        self.preRoll = preRoll
        self.hold = hold
        self.fade = fade
    }

    init(from decoder: Decoder) throws {
        let c = try decoder.container(keyedBy: CodingKeys.self)
        media = c.lenient(.media, 0)
        preRoll = c.lenient(.preRoll, Self.defaultPreRoll)
        hold = c.lenient(.hold, Self.defaultHold)
        fade = c.lenient(.fade, Self.defaultFade)
    }

    /// All four keys under the model's names, so a written gate says every
    /// key (`set_video` merges).
    var dictionary: [String: Any] {
        ["media": media, "pre_roll": preRoll, "hold": hold, "fade": fade]
    }
}

/// The media the Hide While Silent section offers for "Speech from" (CO-94).
enum HideSilentSources {
    /// The media with sound of any clip in `snapshot` (the selected clips
    /// included) whose span overlaps a selected clip's: picture-less media
    /// first — the microphone first — then by total overlap with the
    /// selected clips, longest first, then by id.
    static func candidates(
        for clips: [ClipSnapshot], in snapshot: ProjectSnapshot
    ) -> [MediaSnapshot] {
        var overlap: [UInt32: Ticks] = [:]
        for other in snapshot.clips {
            guard case .media = other.source, let media = snapshot.media(for: other),
                  media.hasAudio
            else { continue }
            for clip in clips {
                let shared = min(other.end, clip.end) - max(other.start, clip.start)
                if shared > 0 { overlap[media.id, default: 0] += shared }
            }
        }
        return overlap.keys.compactMap { snapshot.media($0) }.sorted { a, b in
            if a.hasVideo != b.hasVideo { return !a.hasVideo }
            let (oa, ob) = (overlap[a.id] ?? 0, overlap[b.id] ?? 0)
            if oa != ob { return oa > ob }
            return a.id < b.id
        }
    }
}

/// A gated clip's gate, read off one handle's plan (`gates`, spec §11
/// CO-93) for the timeline's line (`TimelineView+GateLine.swift`). The plan
/// is decoded lazily, at most once, and only when a gated clip is drawn, so a
/// project without one never pays for it. `DuckCurves`' shape.
final class GateCurves {
    private let project: ReelProject
    private var byClip: [UInt32: [PlanRamp]]?

    init(_ project: ReelProject) {
        self.project = project
    }

    /// The clip's gate as ramps in the handle's time, or nil when the plan
    /// has no gate for it.
    func ramps(for clip: UInt32) -> [PlanRamp]? {
        if byClip == nil {
            var found: [UInt32: [PlanRamp]] = [:]
            for gate in project.plan?.gates ?? [] { found[gate.clip] = gate.ramps }
            byClip = found
        }
        return byClip?[clip]
    }
}

