53	extension CanvasLayerBox {
54	    /// `grip` of `region`, in canvas space: the region's centre, or one of
55	    /// its box's handles, taken through `canvasPoint(source:)`.
56	    func obscureGripPoint(_ grip: ObscureGrip, of region: ObscureProps) -> CGPoint {
57	        switch grip {
58	        case .move: return canvasPoint(source: CGPoint(x: region.x, y: region.y))
59	        case .resize(let handle): return canvasPoint(source: handle.point(in: region.box))
60	        }
61	    }
