64	// MARK: - The drag
65	
66	/// Dragging one region's grip. The write is the WHOLE list with one entry
67	/// replaced — never a different length — through the target captured at
68	/// mouse-down (CI-13), so a list the target does not hold at this length is
69	/// never gripped (`PreviewCanvasView.obscureStartList`).
70	struct CanvasObscureSession {
71	    let clip: UInt32
72	    let index: Int
73	    let grip: ObscureGrip
74	    /// The list the write replaces: the target's start state.
75	    let list: [ObscureProps]
76	    /// The box ON SCREEN at mouse-down; the pointer's travel is measured
77	    /// through it, as the region band measures a band.
78	    let frame: CanvasLayerBox
79	    /// The press, in source pixels.
80	    let grab: CGPoint
81	    /// The entry's box, then as dragged; source pixels.
82	    var box: CGRect
83	
84	    /// Each side of a region stays within these, source pixels.
85	    static let minSide = 1.0
86	    static let maxSide = 20000.0
87	
88	    /// Nil when `list` has no entry at `hit.index`.
89	    init?(hit: ObscureRegionHit, list: [ObscureProps], frame: CanvasLayerBox, press: CGPoint) {
90	        guard list.indices.contains(hit.index) else { return nil }
91	        clip = hit.clip
92	        index = hit.index
93	        grip = hit.grip
94	        self.list = list
95	        self.frame = frame
96	        grab = frame.sourcePoint(press)
97	        box = list[hit.index].box
98	    }
99	
100	    var undoName: String {
101	        switch grip {
102	        case .move: return "Move Region"
103	        case .resize: return "Resize Region"
104	        }
105	    }
106	
107	    /// `list` with the entry at `index` placed at `box`: the centre taken
108	    /// from the unrounded rect, then everything rounded the way every canvas
109	    /// gesture rounds (`ZoomRegionSession.region`'s order). The entry's
110	    /// shape, feather, kind and amount are kept.
111	    var regions: [ObscureProps] {
112	        var out = list
113	        let old = list[index]
114	        out[index] = ObscureProps(
115	            shape: old.shape, x: canvasRound(Double(box.midX)), y: canvasRound(Double(box.midY)),
116	            width: canvasRound(Double(box.width)), height: canvasRound(Double(box.height)),
117	            feather: old.feather, kind: old.kind, amount: old.amount)
118	        return out
119	    }
120	
121	    func op(to target: CanvasEditTarget) -> ReelOp {
122	        target.op(video: VideoPatch(obscure: regions), clip: clip)
123	    }
124	
125	    /// `point` is a canvas point; `aboutCentre` is ⌥. The centre grip moves
126	    /// the box by the travel. A handle moves the edge it drives by the
127	    /// travel's component on that axis, the far edge pinned (a side never
128	    /// flips, and never falls under `minSide`), or with ⌥ the centre pinned
129	    /// and both edges moving; an axis it does not drive keeps its extent.
130	    mutating func update(point: CGPoint, aboutCentre: Bool) {
131	        let at = frame.sourcePoint(point)
132	        let d = CGPoint(x: at.x - grab.x, y: at.y - grab.y)
133	        let start = list[index].box
134	        switch grip {
135	        case .move:
136	            box = start.offsetBy(dx: d.x, dy: d.y)
137	        case .resize(let handle):
138	            let x = Self.span(
139	                start.minX, start.maxX, unit: handle.unit.x, travel: d.x, aboutCentre: aboutCentre)
140	            let y = Self.span(
141	                start.minY, start.maxY, unit: handle.unit.y, travel: d.y, aboutCentre: aboutCentre)
142	            box = CGRect(x: x.min, y: y.min, width: x.max - x.min, height: y.max - y.min)
143	        }
144	    }
145	
146	    /// One axis of a resize: `unit` is the handle's -1, 0 or +1 on it.
147	    private static func span(
148	        _ low: CGFloat, _ high: CGFloat, unit: CGFloat, travel: CGFloat, aboutCentre: Bool
149	    ) -> (min: CGFloat, max: CGFloat) {
150	        guard unit != 0 else { return (low, high) }
151	        let lower = CGFloat(minSide)
152	        let upper = CGFloat(maxSide)
153	        if aboutCentre {
154	            let centre = (low + high) / 2
155	            let side = min(max((high - low) + 2 * unit * travel, lower), upper)
156	            return (centre - side / 2, centre + side / 2)
157	        }
158	        if unit > 0 {
159	            let side = min(max(high + travel - low, lower), upper)
160	            return (low, low + side)
161	        }
162	        let side = min(max(high - (low + travel), lower), upper)
163	        return (high - side, high)
164	    }
165	}
