168	/// The selected clip's obscure regions on the canvas (spec §4.2, §11 CI-16):
169	/// each one outlined through the layer's transform, with a move grip at its
170	/// centre and eight resize handles, outside any modal mode. The session is
171	/// `CanvasObscureSession` (one stored property on the frozen view,
172	/// `obscureDrag`); the frozen file carries only the wiring — a press arm, a
173	/// tick arm, a release arm, the cancel, one draw call and one cursor loop.
174	///
175	/// **Order.** The layer's own handles are hit first and a region grip is
176	/// tried only when the press found a body or nothing
177	/// (`CanvasHit.yieldsToObscureGrip`), so a grip under a layer handle is not
178	/// reachable there; a region's inside is not a grip, so a drag there still
179	/// moves the clip. The two modal modes' overlays sit above this whole view
180	/// and take every press while armed; the outlines stay drawn under them.
181	extension PreviewCanvasView {
182	    /// The box whose regions are drawn: the primary box, with exactly one
183	    /// clip selected, unlocked, outside crop mode and the text editor.
184	    var obscureBox: CanvasLayerBox? {
185	        guard selection.count == 1, !cropMode, editingClip == nil,
186	              let box = primaryBox, !box.locked
187	        else { return nil }
188	        return box
189	    }
190	
191	    /// The list a drag replaces — `editTarget`'s start state for the clip —
192	    /// when it has as many entries as the list drawn (the recipe's, at the
193	    /// playhead); nil otherwise, and then no grip exists, because an index
194	    /// would name a different region.
195	    var obscureStartList: [ObscureProps]? {
196	        guard let box = obscureBox else { return nil }
197	        let list = editTarget.start(of: box.clip, in: project).video.obscure
198	        return list.count == box.video.obscure.count ? list : nil
199	    }
200	
201	    /// The region grip under `point` (view space): the nearest within
202	    /// `handleGrab` by the larger axis distance; a tie goes to the higher
203	    /// index (the region drawn later), then to the earlier grip.
204	    func obscureHit(at point: CGPoint) -> ObscureRegionHit? {
205	        guard let box = obscureBox, !box.video.obscure.isEmpty, obscureStartList != nil else {
206	            return nil
207	        }
208	        var best: (hit: ObscureRegionHit, distance: CGFloat)?
209	        for (index, region) in box.video.obscure.enumerated() {
210	            for grip in ObscureGrip.all {
211	                let at = canvasToView(box.obscureGripPoint(grip, of: region))
212	                let distance = max(abs(at.x - point.x), abs(at.y - point.y))
213	                guard distance <= Self.handleGrab else { continue }
214	                if let found = best {
215	                    let closer = distance < found.distance
216	                    let later = distance == found.distance && index > found.hit.index
217	                    guard closer || later else { continue }
218	                }
219	                best = (ObscureRegionHit(clip: box.id, index: index, grip: grip), distance)
220	            }
221	        }
222	        return best?.hit
223	    }
224	
225	    /// Mouse-down on a grip (view space). False when the grip no longer
226	    /// names an entry of the target's list, and the press falls through.
227	    func beginObscureDrag(_ hit: ObscureRegionHit, at point: CGPoint) -> Bool {
228	        guard let box = obscureBox, box.id == hit.clip, let list = obscureStartList else {
229	            return false
230	        }
231	        gestureTarget = editTarget
232	        guard let session = CanvasObscureSession(
233	            hit: hit, list: list, frame: box, press: viewToCanvas(point))
234	        else { return false }
235	        obscureDrag = session
236	        onLiveBegin?()
237	        return true
238	    }
239	
240	    /// One tick (canvas space): one live op, the whole list.
241	    func continueObscureDrag(at point: CGPoint, flags: NSEvent.ModifierFlags) {
242	        guard var session = obscureDrag else { return }
243	        session.update(point: point, aboutCentre: flags.contains(.option))
244	        obscureDrag = session
245	        onLiveUpdate?([session.op(to: gestureTarget)])
246	    }
