250	    /// Every region's outline — a dark backing stroke, then the marquee's
251	    /// dashed line — and, only while the grips exist, their handles and
252	    /// centre crosses.
253	    func drawObscureRegions() {
254	        guard let box = obscureBox else { return }
255	        let regions = box.video.obscure
256	        guard !regions.isEmpty else { return }
257	        let dash: [CGFloat] = [4, 3]
258	        for region in regions {
259	            let path = polygon(box.canvasQuad(ofSource: region.box))
260	            NSColor.black.withAlphaComponent(0.4).setStroke()
261	            path.lineWidth = 2
262	            path.stroke()
263	            path.setLineDash(dash, count: dash.count, phase: 0)
264	            path.lineWidth = 1
265	            DS.marquee.setStroke()
266	            path.stroke()
267	        }
268	        guard obscureStartList != nil else { return }
269	        for region in regions {
270	            drawObscureCentre(canvasToView(box.obscureGripPoint(.move, of: region)))
271	            drawHandles(
272	                CanvasHandle.allCases.map { box.obscureGripPoint(.resize($0), of: region) },
273	                fill: DS.marquee)
274	        }
275	    }
276	
277	    /// The move grip: a 10 pt cross over a dark backing, so it reads on a
278	    /// white frame and a black one.
279	    private func drawObscureCentre(_ centre: CGPoint) {
280	        let arm: CGFloat = 5
281	        let cross = NSBezierPath()
282	        cross.move(to: CGPoint(x: centre.x - arm, y: centre.y))
283	        cross.line(to: CGPoint(x: centre.x + arm, y: centre.y))
284	        cross.move(to: CGPoint(x: centre.x, y: centre.y - arm))
285	        cross.line(to: CGPoint(x: centre.x, y: centre.y + arm))
286	        NSColor.black.withAlphaComponent(0.4).setStroke()
287	        cross.lineWidth = 3
288	        cross.stroke()
289	        DS.marquee.setStroke()
290	        cross.lineWidth = 1.5
291	        cross.stroke()
292	    }
