359	/// Points a pasted clip's gate at this project's media id. An id `map` does
360	/// not carry never stays (it could name another media here): the gate goes,
361	/// `remap_look_media`'s rule (spec §11 CO-92).
362	pub(crate) fn remap_hide_silent(clip: &mut Clip, map: &HashMap<u32, u32>) {
363	    let Some(video) = clip.video.as_mut() else {
364	        return;
365	    };
366	    let Some(gate) = video.hide_silent.as_mut() else {
367	        return;
