446	    /// The gate's settings when `clip` has one and its media has saved
447	    /// speech; `None` is a gate of 1 everywhere.
448	    fn live_gate(&self, clip: &Clip) -> Option<HideSilent> {
449	        let gate = clip.video.as_ref()?.hide_silent?;
450	        self.media(gate.media)?.speech.as_ref()?;
451	        Some(gate)
452	    }
453	
454	    /// The gate at `t` for `instance` among `all`, the media's instances
455	    /// (CO-90): the nearest container, outward from the layer's own, in
456	    /// which one of them covers `t`.
457	    fn gate_among(
458	        &self,
459	        instance: &Instance<'_>,
460	        all: &[Instance<'_>],
461	        gate: &HideSilent,
462	        t: Ticks,
463	        side: Side,
464	    ) -> f64 {
465	        let path: Vec<u32> = instance.inside.iter().map(|e| e.clip.id).collect();
466	        let fade = gate.fade.max(0);
467	        for depth in (0..=path.len()).rev() {
468	            let container = path.get(..depth).unwrap_or(&[]);
469	            let members: Vec<&Instance<'_>> =
470	                all.iter().filter(|i| in_container(i, container)).collect();
471	            if !members.iter().any(|i| covers(i.start, i.end, t, side)) {
472	                continue;
473	            }
474	            let lo = t.saturating_sub(gate.hold.max(0)).saturating_sub(fade);
475	            let hi = t.saturating_add(gate.pre_roll.max(0)).saturating_add(fade);
476	            let spans = self.gate_spans(&members, gate, Some((lo, hi)));
477	            return gate_over(&spans, fade, t, side);
478	        }
479	        1.0
480	    }
481	
482	    /// `instance`'s hide-while-silent gate at project time `t` (CO-90): 1
483	    /// for a clip with none. `side` says which limit a container's edge
484	    /// reads, as `audio.rs`'s envelopes do.
485	    pub(crate) fn hide_silent_gate(&self, instance: &Instance<'_>, t: Ticks, side: Side) -> f64 {
486	        let Some(gate) = self.live_gate(instance.clip) else {
487	            return 1.0;
488	        };
489	        let all = self.media_instances(gate.media);
490	        self.gate_among(instance, &all, &gate, t, side)
491	    }
492	
493	    /// The plan's `gates` (CO-93): one `{clip, ramps}` per timeline-level
494	    /// instance of a gated clip whose media has speech, the ramps tiling
495	    /// its `[start, end)`, `coalesce`d. Empty when no clip has a gate, so
496	    /// the plan writes no key.
497	    pub(crate) fn gate_entries(&self) -> Vec<Value> {
498	        let mut out = Vec::new();
499	        for instance in self.all_instances() {
500	            if !instance.inside.is_empty() {
501	                continue;
502	            }
503	            let Some(gate) = self.live_gate(instance.clip) else {
504	                continue;
505	            };
506	            let all = self.media_instances(gate.media);
507	            let ramps = self.gate_ramps(&instance, &all, &gate);
508	            let mut entry = Map::new();
509	            entry.insert("clip".to_string(), Value::from(instance.clip.id));
510	            entry.insert(
511	                "ramps".to_string(),
512	                Value::Array(ramps.iter().map(json).collect()),
513	            );
514	            out.push(Value::Object(entry));
515	        }
516	        out
517	    }
518	
519	    /// A timeline-level instance's gate as ramps over `[start, end)`: the
520	    /// breakpoints are the instance's ends, every instance of the media's
521	    /// ends, each merged span's `s − fade`, `s`, `e`, `e + fade`, and the
522	    /// midpoint of two spans closer than `2·fade`, where one's fall meets
523	    /// the next one's rise. Between two breakpoints the gate is a straight
524	    /// line, read on the right at the start and on the left at the end.
525	    fn gate_ramps(
526	        &self,
527	        instance: &Instance<'_>,
528	        all: &[Instance<'_>],
529	        gate: &HideSilent,
530	    ) -> Vec<Ramp> {
531	        let fade = gate.fade.max(0);
532	        let members: Vec<&Instance<'_>> = all.iter().collect();
533	        // Windowed as `gate_among` is, and exact by the same argument: an
534	        // instance ending before `start − hold − fade` or starting after
535	        // `end + pre_roll + fade` gives spans whose gate is 0 throughout
536	        // `[start, end]`, so only the instance's neighbourhood is projected.
537	        let lo = instance
538	            .start
539	            .saturating_sub(gate.hold.max(0))
540	            .saturating_sub(fade);
541	        let hi = instance
542	            .end
543	            .saturating_add(gate.pre_roll.max(0))
544	            .saturating_add(fade);
545	        let spans = self.gate_spans(&members, gate, Some((lo, hi)));
546	        let mut breaks = vec![instance.start, instance.end];
547	        for i in all {
548	            breaks.extend([i.start, i.end]);
549	        }
550	        for &(s, e) in &spans {
551	            breaks.extend([s.saturating_sub(fade), s, e, e.saturating_add(fade)]);
552	        }
553	        for pair in spans.windows(2) {
554	            if let (Some(&(_, e1)), Some(&(s2, _))) = (pair.first(), pair.get(1)) {
555	                if s2.saturating_sub(e1) < fade.saturating_mul(2) {
556	                    breaks.push(e1.saturating_add(s2.saturating_sub(e1) / 2));
557	                }
558	            }
559	        }
560	        breaks.retain(|t| *t >= instance.start && *t <= instance.end);
561	        breaks.sort_unstable();
562	        breaks.dedup();
563	        let ramps = breaks
564	            .windows(2)
565	            .filter_map(|pair| match (pair.first(), pair.get(1)) {
566	                (Some(&a), Some(&b)) if b > a => Some(Ramp {
567	                    start: a,
568	                    duration: b.saturating_sub(a),
569	                    from: self.gate_among(instance, all, gate, a, Side::Right),
570	                    to: self.gate_among(instance, all, gate, b, Side::Left),
571	                }),
572	                _ => None,
573	            })
574	            .collect();
575	        coalesce(ramps)
576	    }
577	
578	    /// Every gate naming `media` cleared, on the timeline and in every nest
579	    /// (`remove_media`, spec §11 CO-92).
580	    pub(crate) fn clear_hide_silent(&mut self, media: u32) {
581	        let clips = self
582	            .clips
583	            .iter_mut()
584	            .chain(self.nests.iter_mut().flat_map(|n| n.clips.iter_mut()));
585	        for clip in clips {
586	            if let Some(video) = clip.video.as_mut() {
587	                if video.hide_silent.is_some_and(|gate| gate.media == media) {
588	                    video.hide_silent = None;
589	                }
590	            }
591	        }
592	    }
