// MARK: - The overlay

/// The mode's view: a transparent sheet over the whole canvas pane that takes
/// one drag, draws it, wears the crosshair, and says how to get back out.
///
/// It holds the purpose, the clip and the live session, and nothing else.
/// Where the band landed on the canvas, what the layer under it looks like,
/// and what to do about it are all the view controller's — the same division
/// `CanvasOverlayView` keeps with `PreviewCanvasView`, and the reason the
/// five closures below take and answer plain points and rectangles.
final class CanvasRegionView: CanvasModeOverlay {
    /// What the band is for. Read here only for the hint pill; the commit
    /// branches on the session's copy.
    let purpose: CanvasRegionPurpose
    /// The clip the mode was armed for.
    let clip: UInt32
    /// A second hint pill under the first; nil draws none. A `var` because
    /// what it says is a fact about the CLIP, which can change while the mode
    /// is armed — `syncRegionMode` re-reads it on every `refreshCanvas`.
    var note: String? {
        didSet {
            if note != oldValue { needsDisplay = true }
        }
    }
    /// Live between mouse-down and mouse-up, and nil either side of it.
    private(set) var session: ZoomRegionSession?

    /// A WINDOW point as canvas pixels; nil when there is no canvas to ask.
    var canvasPoint: ((CGPoint) -> CGPoint?)?
    /// A canvas point in this view's own coordinates.
    var viewPoint: ((CGPoint) -> CGPoint)?
    /// The rectangle the zoom will frame, in canvas pixels.
    var resolvedFrame: ((ZoomRegionSession) -> CGRect?)?
    ///    list leaves the end patch at the old length, so that animation
    ///    degrades to a switch at the end until the end state is written
    ///    again. There is no way to say "drop this key" from here — a
    ///    `VideoPatch`'s list keys are single optionals, so nil is absent
    ///    rather than null — and a visible degradation is worth more than an
    ///    invisible append.
    private func structural(video patch: VideoPatch, for clip: ClipSnapshot)
        -> (base: VideoPatch?, animatable: VideoPatch?)
    {
        var base = VideoPatch()
        var animatable = patch
        if let filters = patch.filters,
            filters.count != editedList(clip, action: { $0.filters }, base: { $0.filters }).count
        {
            base.filters = filters
            animatable.filters = nil
        }
        if let obscure = patch.obscure,
            obscure.count != editedList(clip, action: { $0.obscure }, base: { $0.obscure }).count
        {
            base.obscure = obscure
            animatable.obscure = nil
        }
        // A curve is a list too (spec §11 GR-12, GR-32), but not this rule's:
        // every count animates (GR-34). The same count lerps per point, an
        // identity on either side is aligned to the other's x's
        // (`align_identity_curves`), and two curves of different counts blend
        // their values (`curve_blends`). So a curve write with an action
        // selected always goes to the END, a point added or deleted included,
        // and the curve is keyed and blends over the action.
        // Motion is not an animation target (the core refuses it in
        // `set_action_end`), so it ALWAYS lands on the base props.
        if patch.motion != nil {
            base.motion = patch.motion
            animatable.motion = nil
        }
