294	    /// A `handleGrab` square at every grip (view space), empty while the
295	    /// grips do not exist.
296	    func obscureCursorRects() -> [(rect: CGRect, cursor: NSCursor)] {
297	        guard let box = obscureBox, !box.video.obscure.isEmpty, obscureStartList != nil else {
298	            return []
299	        }
300	        let grab = Self.handleGrab
301	        var rects: [(rect: CGRect, cursor: NSCursor)] = []
302	        for region in box.video.obscure {
303	            for grip in ObscureGrip.all {
304	                let centre = canvasToView(box.obscureGripPoint(grip, of: region))
305	                let rect = CGRect(
306	                    x: centre.x - grab / 2, y: centre.y - grab / 2, width: grab, height: grab)
307	                rects.append((rect, grip.cursor))
308	            }
309	        }
310	        return rects
