375	/// Whether `instance` sits in the container named by `path` (the enclosing
376	/// nest clip ids, outermost first; empty for the timeline), at any depth.
377	fn in_container(instance: &Instance<'_>, path: &[u32]) -> bool {
378	    instance.inside.len() >= path.len()
379	        && instance
380	            .inside
381	            .iter()
382	            .zip(path)
383	            .all(|(enclosing, id)| enclosing.clip.id == *id)
384	}
