386	/// One merged span's gate at `t` (CO-90): 1 inside, a ramp to 0 over `fade`
387	/// either side, floored at 0; a step at `fade` 0, `[s, e)` on the right and
388	/// `(s, e]` on the left.
389	fn span_gate(s: Ticks, e: Ticks, fade: Ticks, t: Ticks, side: Side) -> f64 {
390	    if fade <= 0 {
391	        return if covers(s, e, t, side) { 1.0 } else { 0.0 };
392	    }
393	    let off = if t < s {
394	        s.saturating_sub(t)
395	    } else if t > e {
396	        t.saturating_sub(e)
397	    } else {
398	        0
399	    };
400	    (1.0 - off as f64 / fade as f64).max(0.0)
401	}
402	
403	/// The gate at `t` over merged spans: the maximum of each span's, 0 with none.
404	fn gate_over(spans: &[(Ticks, Ticks)], fade: Ticks, t: Ticks, side: Side) -> f64 {
405	    spans
406	        .iter()
407	        .map(|&(s, e)| span_gate(s, e, fade, t, side))
408	        .fold(0.0, f64::max)
409	}
