412	    /// Every instance of `media` in the project, at any depth.
413	    fn media_instances(&self, media: u32) -> Vec<Instance<'_>> {
414	        self.all_instances()
415	            .into_iter()
416	            .filter(|i| matches!(i.clip.source, Source::Media { media: m, .. } if m == media))
417	            .collect()
