420	    /// The merged, widened speech of `members`, each instance's own spans
421	    /// projected at its own origin and kept to its played window; only the
422	    /// ones whose window meets `window` when one is given (CO-90).
423	    fn gate_spans(
424	        &self,
425	        members: &[&Instance<'_>],
426	        gate: &HideSilent,
427	        window: Option<(Ticks, Ticks)>,
428	    ) -> Vec<(Ticks, Ticks)> {
429	        let mut spans: Vec<(Ticks, Ticks)> = Vec::new();
430	        for instance in members {
431	            if let Some((lo, hi)) = window {
432	                if instance.end < lo || instance.start > hi {
433	                    continue;
434	                }
435	            }
436	            spans.extend(self.played_speech(
437	                instance.clip,
438	                instance.origin,
439	                (instance.start, instance.end),
440	            ));
441	        }
442	        spans.sort_unstable();
443	        widened(spans, gate.pre_roll, gate.hold)
444	    }
