814	/// Hide while silent's line (format 43, spec §11 CO-93): over a clip with a
815	/// gate, the gate the core multiplies its opacity by — the plan's `gates`
816	/// entry, read through `TimelineView.gateCurves` — stroked across the clip's
817	/// VIDEO region in teal, gate 1 at the top and 0 at the bottom, so a person
818	/// sees where the camera fades out in each pause and back in before speech.
819	///
820	/// Inside an open nest the timeline's handle is the scope's, so a gate read
821	/// from a container outside the nest is not drawn there (the recipe still
822	/// applies it). An extension of `TimelineContentView` in a file of its own,
823	/// as the duck line is: `TimelineView.swift` is frozen at wiring.
824	extension TimelineContentView {
825	    func drawGateLine(_ clip: ClipSnapshot, in rect: CGRect, owner: TimelineView, visible: CGRect) {
826	        guard clip.video?.hideSilent != nil, rect.height >= 8, rect.width > 1,
827	              let ramps = owner.gateCurves?.ramps(for: clip.id), !ramps.isEmpty
828	        else { return }
829	        let layout = owner.layout
830	        // Flipped: the region's top is its minY, and gate 1 sits there.
831	        func y(_ gate: Double) -> CGFloat {
832	            rect.minY + 1 + CGFloat(1 - min(max(gate, 0), 1)) * (rect.height - 2)
833	        }
834	        let from = max(rect.minX, visible.minX) - 1
835	        let to = min(rect.maxX, visible.maxX) + 1
836	        guard to > from else { return }
837	        // The core's ramps tile the clip's span, so the line is one polyline
838	        // through every ramp that reaches the visible part; one off screen is
839	        // skipped, the ramps being in order.
840	        let path = NSBezierPath()
841	        var started = false
842	        for ramp in ramps {
843	            let start = layout.x(for: ramp.start)
844	            let end = layout.x(for: ramp.start + ramp.duration)
845	            guard end >= from, start <= to else { continue }
846	            let head = CGPoint(x: start, y: y(ramp.from))
847	            if started { path.line(to: head) } else { path.move(to: head) }
848	            started = true
849	            path.line(to: CGPoint(x: end, y: y(ramp.to)))
850	        }
851	        guard started else { return }
852	        NSGraphicsContext.current?.saveGraphicsState()
853	        NSBezierPath(rect: rect).addClip()
854	        NSColor.systemTeal.withAlphaComponent(0.9).setStroke()
855	        path.lineWidth = 1
856	        path.stroke()
857	        NSGraphicsContext.current?.restoreGraphicsState()
858	    }
859	}
